tests.pseudocode:
cases := []struct{ flag, env, model string; want ThinkingLevel }{
  {"low", "", "STANDARD", ThinkingLow},
  {"", "low", "STANDARD", ThinkingLow},
  {"", "", "STANDARD", ThinkingHigh},
  {"", "", "anthropic/claude-opus-5-5", ThinkingUnset},
}
for _, c := range cases {
  t.Setenv("AF_MODEL_EFFORT", c.env)
  common := Common{Effort: c.flag, Model: c.model}
  choice, err := common.ResolveModelNamed(c.model)
  assert err == nil
  assert choice.Thinking == c.want
}

for _, v := range []string{"HIGH", "High", "hIgH"} {
  fs := flag.NewFlagSet("t", flag.ContinueOnError)
  c := &Common{}
  c.Register(fs)
  fs.Parse([]string{"--effort", v})
  assert c.Effort == "high"
}

// stub ClampThinkingLevel to return (high, true) for xhigh
c := &Common{Effort: "xhigh", Model: "test/limited-model"}
choice, err := c.ResolveModelNamed("test/limited-model")
assert err == nil
assert choice.Thinking == ThinkingHigh

// stub ClampThinkingLevel to return ("", false)
c := &Common{Effort: "high", Model: "test/no-thinking-model"}
_, err := c.ResolveModelNamed("test/no-thinking-model")
assert isUsageError(err)
assert strings.Contains(err.Error(), "test/no-thinking-model")

// case 1
opts := implFlags{repairModel: "ADVANCED"}
common := Common{Effort: "low", Model: "STANDARD"}
// repairModelEffort = "high"
repairChoice := resolveRepairModel(common, opts)
assert repairChoice.Thinking == ThinkingHigh

// case 2
opts2 := implFlags{repairModel: "ADVANCED"}
common2 := Common{Effort: "low", Model: "STANDARD"}
repairChoice2 := resolveRepairModel(common2, opts2)
assert repairChoice2.Thinking == ThinkingXHigh

// case 3
opts3 := implFlags{}
common3 := Common{Effort: "low", Model: "STANDARD"}
repairChoice3 := resolveRepairModel(common3, opts3)
assert repairChoice3.Thinking == ThinkingLow

// stub ClampThinkingLevel to return (medium, true) for xhigh
choice, warnings := resolveRepairModel(common, opts)
assert choice.Thinking == ThinkingMedium
assert any(warnings, func(w Warning) bool {
  return w.Code == WarnEffortClamped && strings.Contains(w.Message, "repair")
})

t.Setenv("AF_REPAIR_MODEL_EFFORT", "high")
opts := implFlags{repairModel: "STANDARD"}
common := Common{Model: "STANDARD"}
repairChoice := resolveRepairModel(common, opts)
// STANDARD tier's own effort (high), not from env
assert repairChoice.Thinking == ThinkingHigh

// Compile-time: tierTable is declared as map[string]map[ModelTier]tierEntry
// Runtime check:
for vendor, byTier := range tierTable {
  for tier, entry := range byTier {
    assert entry.spec != ""
    // The type system enforces no variant dimension
  }
}
// The extended model spec should not appear
assert tierTable["anthropic"][TierAdvanced].spec != "anthropic/claude-fable-5-1"

// This is a compile-time check: the test file calls
// ModelSpec("STANDARD", "") and ResolveModel("STANDARD", "")
// and the build succeeds. A call with three args would fail.
spec, thinking, err := ModelSpec("STANDARD", "")
assert err == nil
assert spec != ""

// Source inspection: read cli.go, find ResolveModelNamed,
// assert the call to agentrun.ResolveModel has two arguments
src := readFile("internal/toolio/cli.go")
assert !strings.Contains(src, "c.Variant")
// Also a compile-time check: ResolveModel(spec, vendor) compiles

for _, vendor := range TierVendors() {
  for _, tier := range Tiers {
    m, thinking, _ := ResolveModel(string(tier), vendor)
    if thinking == ThinkingUnset { continue }
    clamped, ok := catalog.ClampThinkingLevel(m, thinking)
    assert ok
    assert clamped == thinking
  }
}
